"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["72544"],{90919(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.endereco_referencia.cidade_incoerente","status":422,"titulo":"Cidade do endere\xe7o diverge da refer\xeancia de cidade da entidade"},"descricao":{"codigo":"uniplus.endereco_referencia.cidade_incoerente","requisitos":[],"oQueAconteceu":["A cidade que o CEP resolveu, no objeto `cidade` do endere\xe7o, n\xe3o \xe9 a cidade informada no cadastro (`cidadeCodigoIbge`, `cidadeNome` e `cidadeUf`): o c\xf3digo IBGE \xe9 diferente, ou a UF \xe9 diferente (a UF \xe9 comparada sem distinguir mai\xfasculas de min\xfasculas). A mensagem \xe9 `A cidade do endere\xe7o (resolvida pelo CEP) deve coincidir com a refer\xeancia de cidade da entidade.`","Esta confer\xeancia s\xf3 ocorre quando o endere\xe7o passou em todas as confer\xeancias pr\xf3prias e a cidade do cadastro \xe9 v\xe1lida; se alguma delas falhou, a resposta traz essa recusa, e esta fica para depois da corre\xe7\xe3o. No campus e no local de oferta a cidade do cadastro \xe9 obrigat\xf3ria. Na institui\xe7\xe3o ela \xe9 opcional, e o endere\xe7o sem cidade no cadastro recebe a recusa de [cidade obrigat\xf3ria com endere\xe7o](/erros/uniplus.endereco_referencia.cidade_obrigatoria_com_endereco).","O endere\xe7o estruturado \xe9 opcional no cadastro do campus, do local de oferta e da institui\xe7\xe3o (a sede): sem o objeto `endereco` no corpo da requisi\xe7\xe3o, nenhuma confer\xeancia dele ocorre. Com o objeto, a API confere os campos um de cada vez e para na primeira recusa, nesta ordem: CEP informado, CEP com 8 d\xedgitos, cidade do endere\xe7o (as recusas da fam\xedlia [refer\xeancia de cidade](/erros/uniplus.cidade_referencia.codigo_ibge_obrigatorio)), tamanho dos textos (logradouro, n\xfamero, complemento, bairro e distrito), latitude, longitude, n\xedvel de resolu\xe7\xe3o informado, n\xedvel de resolu\xe7\xe3o dentro do vocabul\xe1rio, origem informada e tamanho da origem.","A recusa vem na lista `errors` da resposta, com `field` igual a `endereco`, ao lado das recusas dos outros campos do mesmo cadastro, que s\xe3o conferidos no mesmo pedido. O `code` da resposta \xe9 o da primeira recusa da lista, e as recusas dos campos do pr\xf3prio cadastro (como `sigla`, `nome` e a cidade) v\xeam antes da do endere\xe7o. Nada \xe9 gravado. Na atualiza\xe7\xe3o, estas confer\xeancias v\xeam antes da busca do registro: um `{id}` que n\xe3o existe, enviado com endere\xe7o recusado, recebe esta recusa, e s\xf3 o corpo aceito chega \xe0 resposta de [campus n\xe3o encontrado](/erros/uniplus.configuracao.campus.nao_encontrado), de [local de oferta n\xe3o encontrado](/erros/uniplus.configuracao.local_oferta.nao_encontrado) ou de [institui\xe7\xe3o n\xe3o encontrada](/erros/uniplus.organizacao.instituicao.nao_encontrada)."],"comoResolver":["Fa\xe7a o endere\xe7o e o cadastro apontarem para o mesmo munic\xedpio: o `cidade.codigoIbge` do endere\xe7o igual ao `cidadeCodigoIbge` do cadastro, e a mesma UF nos dois."],"ondeAparece":["Cria\xe7\xe3o de um campus","Atualiza\xe7\xe3o de um campus","Cria\xe7\xe3o de um local de oferta","Atualiza\xe7\xe3o de um local de oferta","Cria\xe7\xe3o da institui\xe7\xe3o","Atualiza\xe7\xe3o da institui\xe7\xe3o"]},"modulo":{"id":"transversais","nome":"Erros transversais","assunto":"Endereco referencia"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"d146f1ba7c5762ff6b06be66801aa6e88c9be916"}}')}}]);